use vstd::prelude::*;

verus! {
    fn ones(n: usize) -> (result: Vec<i8>)
        ensures
            result.len() == n,
            forall(|i: usize| (i < n) ==> result[i] == 1),
            forall(|i: usize, j: usize| (i < n && j < n) ==> result[i] == result[j]),
            forall(|i: usize| (i < n) ==> result[i] > 0),
    {
        let mut v: Vec<i8> = Vec::new();
        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                v.len() == i,
                forall(|k: usize| (k < i) ==> v[k] == 1),
            decreases n - i,
        {
            v.push(1);
            i = i + 1;
        }
        result = v;
    }
}
fn main() {}

